@js:
var m = baseUrl.match(/\/chapter\/(\d+)\/(\d+)\.html/);
var aid = m[1];
var cid = m[2];
var api = 'https://mhbao.colacomic.com/api/comic/read/pics';
var UA = 'Mozilla/5.0 (Linux; Android 10; wv) AppleWebKit/537.36 (KHTML, like Gecko) Version/4.0 Chrome/78.0.3904.108 Mobile Safari/537.36 SearchCraft/3.6.5 (Baidu; P1 9.0)';
var imgOpts = ',' + JSON.stringify({headers: {'User-Agent': UA, Referer: 'https://mhbao.colacomic.com/'}});
var urls = [];
var offset = 0;
while (true) {
  var opts = ',' + JSON.stringify({method: 'POST', headers: {'User-Agent': UA}, body: 'id=' + cid + '&aid=' + aid + '&offset=' + offset + '&limit=5'});
  var res = java.ajax(api + opts);
  var d = JSON.parse(res);
  if (d.code != 1 || !d.data || !d.data.pic || d.data.pic.length === 0) break;
  for (var i = 0; i < d.data.pic.length; i++) {
    var p = d.data.pic[i].pic.trim();
    urls.push('<img src="' + p + imgOpts + '">');
  }
  if (d.data.pic.length < 5) break;
  offset += 5;
}
result = urls.join('\n');
